// Una lengua de fuego: núcleo en las columnas x0..x1, empieza en y0 y mide n filas.
function halo(x0, x1, y0, n) {
  const w = x1 - x0 + 1;
  for (let i = 1; i < n; i++) {
    const e = i < n - 1 ? 2 : 1;
    fill_rect(x0 - e, y0 + i, w + 2 * e, 1, "#fff6ef");
  }
  fill_rect(x0 - 1, y0 + n, w + 2, 1, "#f2f1f0f2");
  fill_rect(x0, y0 + n + 1, w, 1, "#9c9a9a9c");
}

function lengua(x0, x1, y0, n, nucleo) {
  const w = x1 - x0 + 1;
  const naranja = Math.max(1, Math.floor(n / 2));
  for (let i = 0; i < n; i++) {
    const y = y0 + i;
    if (i === 0) {
      fill_rect(x0 - 1, y, w + 2, 1, "#ff8a1e");
      fill_rect(x0, y, w, 1, nucleo);
    } else if (i <= naranja) {
      fill_rect(x0 - 1, y, w + 2, 1, "#ffc397");
      fill_rect(x0, y, w, 1, i === 1 ? "#ff8f3e" : "#ff7f1b");
    } else if (i < n - 1) {
      fill_rect(x0, y, w, 1, "#ffc397");
    } else {
      fill_rect(x0, y, w, 1, "#ffdfc6");
    }
  }
}

// Fuego animado de las tres toberas: ls = largo de las laterales, lc = largo de la central.
part("fuego", ({ ls, lc, brillo }) => {
  const nucleo = brillo ? "#fff6ce" : "#ffcc3f";
  halo(27, 27, 57, ls);
  halo(36, 36, 57, ls);
  halo(31, 32, 58, lc);
  lengua(27, 27, 57, ls, nucleo);
  lengua(36, 36, 57, ls, nucleo);
  lengua(31, 32, 58, lc, nucleo);
});

// Una función por acción: dibuja el frame f desde cero. t va de 0 a 1.
action("motor", { frames: 4, fps: 12, loop: true }, (f, { t }) => {
  draw("casco");
  // corta, larga, media, larga
  const largos = [
    { ls: 3, lc: 4, brillo: false },
    { ls: 6, lc: 8, brillo: true },
    { ls: 4, lc: 6, brillo: false },
    { ls: 5, lc: 8, brillo: true },
  ];
  draw("fuego", cycle(largos, f));
});

